WITH cities AS (
  SELECT 
    DISTINCT LOWER(municipio_clean) AS city_name
  FROM
    datalake_seo_keywords_clusters.ibge_cities
  WHERE
    municipio_clean IS NOT NULL
    AND municipio_clean != ' '
),
keywords AS (
  SELECT
    *
  FROM 
    datalake_google_search_console_classified.gsc_keywords_region_url_match_bra
  WHERE
    dt_created BETWEEN DATE('{load_start_date}') AND DATE('{load_end_date}')
),
general_city_level_enrichment AS (
  SELECT
    keyword,
    keyword_clean,
    CASE
      WHEN CONTAINS(c.city_name, ' ') THEN city_name
      WHEN ARRAY_CONTAINS(SPLIT(keyword_clean, ' '), LOWER(c.city_name)) THEN city_name
      WHEN CONTAINS(keyword_clean, 'sao paulo') THEN COALESCE(c.city_name, 'sao paulo')
      WHEN RLIKE(keyword_clean, r'.*(\bsp\b).*') THEN COALESCE(c.city_name, 'sao paulo')
      WHEN RLIKE(keyword_clean, r'.*(\brj\b).*') THEN COALESCE(c.city_name, 'rio de janeiro')
      WHEN CONTAINS(keyword_clean, ' bh') THEN COALESCE(c.city_name, 'belo horizonte')
      WHEN CONTAINS(keyword_clean, ' sjc') THEN COALESCE(c.city_name, 'sao jose dos campos')
      WHEN CONTAINS(keyword_clean, ' santo andre') THEN COALESCE(c.city_name, 'santo andre')
      WHEN CONTAINS(keyword_clean, ' sao caetano') THEN COALESCE(c.city_name, 'sao caetano do sul')
      WHEN CONTAINS(keyword_clean, ' goiania') THEN COALESCE(c.city_name, 'goiania')
      WHEN CONTAINS(keyword_clean, ' nova iguacu') THEN COALESCE(c.city_name, 'nova iguacu')
      WHEN CONTAINS(keyword_clean, ' sao goncalo') THEN COALESCE(c.city_name, 'sao goncalo')
      WHEN CONTAINS(keyword_clean, ' carapicuiba') THEN COALESCE(c.city_name, 'carapicuiba')
      WHEN CONTAINS(keyword_clean, ' sbc') THEN COALESCE(c.city_name, 'sao bernardo do campo')
      WHEN CONTAINS(keyword_clean, ' sbo') THEN COALESCE(c.city_name, 'santa barbara do oeste')
      WHEN CONTAINS(keyword_clean, ' vcp') THEN COALESCE(c.city_name, 'campinas')
      WHEN CONTAINS(keyword_clean, ' vix') THEN COALESCE(c.city_name, 'vitória')
      WHEN CONTAINS(keyword_clean, ' gru') THEN COALESCE(c.city_name, 'guarulhos')
      WHEN CONTAINS(keyword_clean, ' sao bernardo do campo') THEN COALESCE(c.city_name, 'sao bernardo do campo')
      ELSE COALESCE(c.city_name, '')
    END AS match_ibge_city,
    page,
    CASE 
      WHEN regexp_like(page,'rio-de-janeiro|freguesia-jacarepagua|jacarepagua|meier|pechincha|guaratiba|cachambi|vila-valqueire|engenho-de-dentro|jardim-oceanico|curicica|praca-seca|cosmos|vila-da-penha|braz-de-pina|lins-de-vasconcelos|penha-circular|del-castilho|inhoaiba|cascadura|bento-ribeiro|cosme-velho|jardim-sulacap|pilares|quintino-bocaiuva|cordovil|parada-de-lucas|freguesia-ilha-do-governador|colegio|vila-kosmos|honorio-gurgel|estacio|vaz-lobo|marechal-hermes|pedra-de-guaratiba|rocha-miranda|maria-da-graca|cocota|praia-da-bandeira|senador-vasconcelos|cavalcanti|monero|senador-camara|gardenia-azul|engenho-da-rainha|catumbi|engenheiro-leal|ricardo-de-albuquerque|vigario-geral|barra-de-guaratiba|magalhaes-bastos|ilha-de-guaratiba|sepetiba|ilha-do-governador|campo-dos-afonsos|costa-barros|barros-filho')
        THEN 'RJ'
 
      WHEN regexp_like(page,'porto-alegre|tristeza|hipica|partenon|cavalhada|central-parque|jardim-itu-sabara|praia-de-belas|chacara-das-pedras|azenha|tres-figueiras|belem-novo|rubem-berta|parque-santa-fe|campo-novo|mario-quintana|jardim-isabel|pedra-redonda|agronomia|alto-petropolis|lami|belem-velho|costa-e-silva|ecoville|coronel-aparicio-borges|vila-joao-pessoa|parque-dos-maias|arquipelago|nova-ipanema|jardim-itati')
        THEN 'POA'
 
      WHEN regexp_like(page,'belo-horizonte|nova-suissa|manacos|colegio-batista|carlos-prates|alto-barroca|alipio-de-melo|bandeirantes-pampulha|alto-caicaras|vila-cloris|diamante|vila-sao-joao-batista|vila-piratininga|caicara-adelaide|juliana|comiteco|esplanada|leticia|alvaro-camargos|novo-gloria|diamante-barreiro|tirol-barreiro|estrela-do-oriente|vila-nova-gameleira-i|dom-cabral|etelvina-carneiro|ana-lucia-venda-nova|vila-engenho-nogueira|miramar-barreiro|maria-virginia|minascaixa|conjunto-california-i|santa-helena-barreiro|caicara|milionarios-barreiro|serra-verde-venda-nova|antonio-ribeiro-de-abreu|conjunto-celso-machado|frei-leopoldo|tupi-a|cenaculo|ermelinda|vila-minaslandia|eymard|ouro-minas|vila-madre-gertrudes-i|cardoso-barreiro|sao-jose-pampulha|tupi-b|parque-copacabana|teixeira-dias-barreiro|brasil-industrial-barreiro|jardim-dos-comerciarios-venda-nova|lindeia-barreiro|pousada-santo-antonio|granja-de-freitas|parque-sao-pedro-venda-nova|solar-do-barreiro-barreiro|conjunto-bonsucesso|vila-oeste|solimoes|aarao-reis|xodo-marize|nova-cintra|taquaril|conjunto-tunel-ibirite|sao-tomaz|novo-sao-lucas|olaria-barreiro|leblon-venda-nova|mangueiras-barreiro|vila-magnesita|vila-santa-rita-vale-do-jatoba-barreiro|conjunto-lagoa|parque-pedro-ii|jardim-pirineus|flavio-de-oliveira|industrias-i-barreiro|jardim-europa|jonas-veiga|maria-tereza|flavio-de-oliveira-barreiro|santa-cruz-barreiro|vila-independencia-i|cidade-jardim-taquaril|conjunto-minascaixa|conjunto-taquaril|glalija|indians|itaipu-barreiro|mineirao|pongelupe-barreiro|madri|novo-santa-cecilia-barreiro|novo-tupi|parque-sao-joao-batista|santa-margarida-barreiro|ventosa|capitao-eduardo|conjunto-ademar-maldonado-barreiro|distrito-industrial|flavio-marques-lisboa-barreiro|mariano-de-abreu|santa-cecilia-vale-do-jatoba-barreiro|vale-do-jatoba-barreiro|adelaide|cabana|castanheira-i-vale-do-jatoba-barreiro|conjunto-helena-antipoff|conjunto-santa-maria|conjunto-tunel-ibirite-barreiro|leonina|marilandia-jatoba-barreiro|marcola|vila-barragem-santa-lucia|vila-petropolis|vila-pinho-vale-do-jatoba-barreiro|vila-atila-de-paiva')
        THEN 'BH'

      WHEN regexp_like(page,'brasilia|distrito-federal|setor-de-mansoes-dom-bosco|superquadra-noroeste|samambaia|setor-de-mansoes-lago-norte|setor-de-hoteis-e-turismo-norte|setor-de-armazenagem-e-abastecimento-norte|mansoes-do-lago|setor-de-multiplas-atividades-sul|centro-comercial-noroeste|centro-de-atividades|quadra-mista-sudoeste|setor-de-garagens-e-concessionarias-de-veiculos|setor-de-grandes-areas-norte')
