      WHEN regexp_like(page,'curitiba|bigorrilho|campo-comprido|bacacheri|juveve|cic|mossungue|ahu|capao-raso|pilarzinho|hauer|alto-boqueirao|campina-do-siqueira|hugo-lange|umbara|abranches|tatuquara|butiatuvinha|capao-da-imbuia|fanny|parolin|ganchinho|neoville|parque-tangua|jardim-schaffer')
