      WHEN regexp_like(page,'campinas|sorocaba|jundiai|santos|praia-grande|sao-jose-dos-campos|guaruja|jardim-proenca|vila-itapura|mansoes-santo-antonio|parque-prado|chacara-da-barra|parque-jambeiro|parque-imperador|jardim-novo-campos-eliseos|sitios-de-recreio-gramado|parque-sao-quirino|barao-geraldo|loteamento-parque-sao-martinho|loteamento-caminhos-de-san-conrado-sousas|vila-brandina|jardim-eulina|cidade-satelite-iris|parque-xangrila|parque-residencial-vila-uniao|jardim-campos-eliseos|parque-alto-taquaral|parque-via-norte|vila-marieta|jardim-santa-genebra|residencial-parque-da-fazenda|bairro-das-palmeiras|vila-joao-jorge|vila-proost-de-souza|jardim-antonio-von-zuben|jardim-do-lago-continuacao|jardim-garcia|parque-italia|vila-mimosa|residencial-jatibela|parque-das-universidades|chacara-santa-margarida|jardim-myrian-moreira-da-costa|loteamento-mont-blanc-residence|recanto-dos-dourados|parque-jatibaia-sousas|colinas-do-ermitage-sousas|ville-sainte-helene|parque-da-hipica|parque-fazendinha|jardim-botanico-sousas|jardim-carlos-lourenco|vila-joaquim-inacio|swift|tijuco-das-telhas|jardim-paranapanema|fazenda-sao-quirino|jardim-conceicao-sousas|jardim-ipaussurama|vila-padre-manoel-de-nobrega|residencial-cosmos|loteamento-residencial-barao-do-cafe|loteamento-residencial-vila-bella|parque-dos-alecrins|vila-saturnia|chacara-sao-rafael|bosque-de-barao-geraldo|parque-das-quaresmeiras|fazenda-santa-candida|fundacao-da-casa-popular|parque-universitario-de-viracopos|parque-dos-pomares|residencial-terras-do-barao|loteamento-center-santa-genebra|loteamento-arboreto-dos-jequitibas-sousas|jardim-novo-maracana|jardim-londres|loteamento-chacaras-vale-das-garcas|jardim-capivari|notre-dame|parque-valenca-i|vila-rossi-borghi-e-siqueira|jardim-florence|vila-hollandia|conjunto-habitacional-padre-anchieta|bosque-das-palmeiras|vila-sonia-sousas|jardim-proenca-i|jardim-paraiso-de-viracopos|jardim-martinelli-sousas|chacaras-campos-dos-amarais|vila-miguel-vicente-cury|conjunto-residencial-parque