    END AS city_abbreviation,
    structure,
    business_context,
    country,
    state,
    city,
    neighborhood,
    position,
    impressions,
    clicks,
    ctr,
    site_url,
    posimp,
    device,
    domain,
    is_branded,
    has_region,
    dt_created,
    year,
    month,
    day
  FROM
    keywords AS k
  LEFT JOIN 
    cities AS c
      ON CHARINDEX(LOWER(c.city_name), LOWER(k.keyword_clean)) > 0
  QUALIFY ROW_NUMBER() OVER(
    PARTITION BY dt_created, keyword_clean, page, device
    ORDER BY LENGTH(match_ibge_city) DESC, CHARINDEX(match_ibge_city, keyword_clean)
    DESC
  ) = 1
)
SELECT 
  keyword,
  keyword_clean,
  match_ibge_city,
  page,
  city_abbreviation,
  structure,
  business_context,
  site_url,
  device,
  domain,
  country,
  state,
  city,
  neighborhood,
  position,
  impressions,
  clicks,
  ctr,
  posimp,
  is_branded,
  has_region,
  CASE
    WHEN match_ibge_city != '' THEN 1
    ELSE 0
  END AS has_mention_to_city,
  dt_created,
  year,
  month,
